import firebase_admin
from firebase_admin import credentials
from dataclasses import dataclass

@dataclass
class FirebaseConfig:
    project_id: str
    # In a real application, you might load service account credentials here
    # For simplicity, we'll assume the project ID is sufficient for initialization
    # if running in a Google Cloud environment or with FIREBASE_CONFIG environment variable set.

def get_firebase_app(config: FirebaseConfig):
    try:
        return firebase_admin.get_app()
    except ValueError:
        # If running outside a Google Cloud environment, you might need
        # to explicitly provide credentials. For this exercise, we assume
        # that if the app is not found, we can initialize it with just the project_id.
        # A more robust solution would involve loading service account credentials.
        # For local development, 'firebase_admin.initialize_app()' can often infer
        # credentials if GOOGLE_APPLICATION_CREDENTIALS environment variable is set.
        return firebase_admin.initialize_app(options={"projectId": config.project_id})

import requests
import os
from identity_models import EmailPasswordLoginRequest, EmailPasswordLoginResponse

def email_password_login(payload: EmailPasswordLoginRequest):
    api_key = os.environ.get("FIREBASE_WEB_API_KEY")
    if not api_key:
        raise ValueError("FIREBASE_WEB_API_KEY environment variable not set.")

    rest_api_url = f"https://identitytoolkit.googleapis.com/v1/accounts:signInWithPassword?key={api_key}"
    headers = {"Content-Type": "application/json"}
    data = {
        "email": payload.email,
        "password": payload.password,
        "returnSecureToken": True
    }

    response = requests.post(rest_api_url, headers=headers, json=data)
    response.raise_for_status()
    response_data = response.json()

    return EmailPasswordLoginResponse(
        id_token=response_data["idToken"],
        refresh_token=response_data["refreshToken"],
        expires_in=response_data["expiresIn"]
    )

import requests
import os
from identity_models import RefreshSessionRequest, RefreshSessionResponse

def refresh_session(payload: RefreshSessionRequest):
    api_key = os.environ.get("FIREBASE_WEB_API_KEY")
    if not api_key:
        raise ValueError("FIREBASE_WEB_API_KEY environment variable not set.")

    rest_api_url = f"https://securetoken.googleapis.com/v1/token?key={api_key}"
    headers = {"Content-Type": "application/json"}
    data = {
        "grant_type": "refresh_token",
        "refresh_token": payload.refresh_token
    }

    response = requests.post(rest_api_url, headers=headers, json=data)
    response.raise_for_status()
    response_data = response.json()

    return RefreshSessionResponse(
        id_token=response_data["id_token"],
        refresh_token=response_data["refresh_token"],
        expires_in=response_data["expires_in"]
    )

import requests
import os
from identity_models import PasswordResetRequest, PasswordResetResponse

def password_reset(payload: PasswordResetRequest):
    api_key = os.environ.get("FIREBASE_WEB_API_KEY")
    if not api_key:
        raise ValueError("FIREBASE_WEB_API_KEY environment variable not set.")

    rest_api_url = f"https://identitytoolkit.googleapis.com/v1/accounts:sendOobCode?key={api_key}"
    headers = {"Content-Type": "application/json"}
    data = {
        "requestType": "PASSWORD_RESET",
        "email": payload.email
    }

    response = requests.post(rest_api_url, headers=headers, json=data)
    response.raise_for_status()

    return PasswordResetResponse(message="Password reset email sent successfully.")
